contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 d) internal {
        d = bound(d, 0, 1000000000000000000000000000000);
        d = bound(d, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(d > 0);
        try c.Deposit{value: d}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint ethBefore = address(c).balance;
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: d}() {} catch { return; }
